entries[137660] = { ["name"] = "The Silver Hand", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Mace\n5 - 7 Damage Speed 3.60\n(1.7 damage per second)\n+22 Intellect\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\n\nHoly Artifact Relic Slot\nLife Artifact Relic Slot\nUse: Releases the Light within yourself, healing 5 injured allies instantly and an injured ally every 1 sec for 20 sec within 40 yds for (35.1% of Spell Power).\n\nAllies healed also receive 12% increased healing from your Holy Light, Flash of Light, and Holy Shock spells for 12 sec. (1 Min, 30 Sec Cooldown)\n\"We never intended this path. Now... now this young world faces annihilation.\"" }
entries[137661] = { ["name"] = "Truthguard", ["text"] = "Binds when picked up\nUnique\nOff Hand Shield\n52 Armor\n+2 Strength\n+7 Intellect\n+4 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nHoly Artifact Relic Slot\nIron Artifact Relic Slot\nUse: Releases a blinding flash from Truthguard , causing (56.7% of Attack Power) Holy damage to all nearby enemies within 8 yds and reducing all damage they deal to you by 25% for 9 sec. (1 Min Cooldown)\n\"This shield will shine light upon Loken's lies and treachery. Would that I could stay with you and help you fight this war.\"" }
entries[137663] = { ["name"] = "Soft Foam Sword", ["text"] = "Binds when picked up\nToy\nUse: Mortally wound an enemy of trivial difficulty.\nSell Price:" }
entries[137676] = { ["name"] = "Coded Message", ["text"] = "Quest Item\n\"The words are indecpiherable without some sort of key.\"" }
entries[137677] = { ["name"] = "Fel Blood", ["text"] = "Quest Item\n\"There are few things in this world that are more vile.\"" }
entries[137678] = { ["name"] = "Fel Cipher", ["text"] = "Quest Item\n\"Used to decode messages sent between Veiled Hand members.\"" }
entries[137680] = { ["name"] = "Plans: Leystone Greaves", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to make Leystone Greaves.\nReduces the materials required to craft Leystone Greaves.\nRequires Legion Blacksmithing (1)\n\nLeystone Greaves\nBinds when equipped\nLegs Plate\n16 Armor\n+5 [Strength or Intellect]\n+7 Stamina\nDurability 100 / 100\nSell Price:\nRequires Leystone Ore (24), Foxflower Flux (2)\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[137681] = { ["name"] = "Pattern: Bloodtotem Saddle Blanket", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Bloodtotem Saddle Blanket.\nCraft a Silkweave Saddle Blanket.\nRequires Legion Tailoring (100)\n\nBloodtotem Saddle Blanket\nUse: Place a saddle blanket onto your mount, making your mount much more comfortable for 2 hrs.\n\nThe effect's duration is quadrupled for tailors.\nRequires Shal'dorei Silk (25)" }
entries[137686] = { ["name"] = "Steelbound Harness", ["text"] = "Mount\n(Account-wide)\nUse: Teaches you how to summon a rideable Steelbound Devourer.\nSummons and dismisses your Steelbound Devourer.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Only the sturdiest-forged chains can restrain this beast.\"\nProfession:\nBlacksmithing" }
entries[137687] = { ["name"] = "Plans: Fel Core Hound Harness", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Fel Core Hound Harness.\nCraft a Fel Core Hound Harness.\nRequires Legion Blacksmithing (100)\nSteelbound Harness\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Steelbound Devourer.\nSummons and dismisses your Steelbound Devourer.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Only the sturdiest-forged chains can restrain this beast.\"\nProfession:\nBlacksmithingRequires Demonsteel Bar (100), Blood of Sargeras (50), Infernal Brimstone (10), Felhide (10)" }
entries[137690] = { ["name"] = "Blood Offering", ["text"] = "Quest Item\nUse: Make the demonic offering of blood to complete the ritual and make contact with the soul of Illidan Stormrage. (15 Sec Cooldown)" }
entries[137691] = { ["name"] = "Schematic: Intra-Dalaran Wormhole Generator", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft an Intra-Dalaran Wormhole Generator.\nCraft an Intra-Dalaran Wormhole Generator.\nRequires Legion Engineering (1)\nSell Price:\nIntra-Dalaran Wormhole Generator\nUse: Teleport to a point up to 90 yards away. Can only be used in Dalaran.\nSell Price:\nRequires Leystone Ore (150), Chaos Blaster , Felwort (3)" }
entries[137692] = { ["name"] = "Schematic: Blingtron's Circuit Design Tutorial", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Blingtron's Circuit Design Tutorial.\nCraft Blingtron's Circuit Design Tutorial.\nRequires Legion Engineering (1)\nSell Price:\nBlingtron's Circuit Design Tutorial\nToy\nUse: Play a circuit-uncrossing game.\nSell Price:\nRequires Leystone Ore (50), Felslate (50), Infernal Brimstone (5)" }
