entries[137725] = { ["name"] = "Schematic: Sonic Environment Enhancer", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Sonic Environment Enhancer.\nCraft a Sonic Environment Enhancer.\nRequires Legion Engineering (1)\nSell Price:\nSonic Environment Enhancer\nUse: Play music.\n\nYou can change the music by using Song Scrolls, which are crafted by scribes.\nSell Price:\nRequires Leystone Ore (50), Felslate (50), Felwort" }
entries[137726] = { ["name"] = "Schematic: Leystone Buoy", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Leystone Buoy.\nCraft a Leystone Buoy.\nRequires Legion Engineering (1)\nSell Price:\nLeystone Buoy\nUse: Requires you to be underwater to use. Especially useful when you're about to run out of breath.\nSell Price:\nRequires Leystone Ore (3)" }
entries[137727] = { ["name"] = "Schematic: Mecha-Bond Imprint Matrix", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Mecha-Bond Imprint Matrix.\nCraft a Mecha-Bond Imprint Matrix.\nRequires Legion Engineering (1)\nSell Price:\nMecha-Bond Imprint Matrix\nClasses: Hunter\nUse: Allows you to tame and track pets in the Mechanical family.\nAllows you to tame pets in the Mechanical family.\nShows the location of all nearby mechanicals on the minimap.\nSell Price:\nRequires Leystone Ore (5), Blood of Sargeras (20), Felwort" }
entries[137728] = { ["name"] = "Technique: Scroll of Forgotten Knowledge", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Scroll of Forgotten Knowledge.\nCraft a Scroll of Forgotten Knowledge.\nRequires Legion Inscription (1)\nSell Price:\nScroll of Forgotten Knowledge\nUse: Read the scroll and learn something.\nSell Price:\nRequires Light Parchment , Roseate Pigment (35)" }
entries[137729] = { ["name"] = "Technique: Codex of the Tranquil Mind", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Codex of the Tranquil Mind.\nCraft a Codex of the Tranquil Mind.\nRequires Legion Inscription (1)\nSell Price:\nCodex of the Tranquil Mind\nUse: Set out a codex, allowing nearby players to adjust their talents. Cannot affect targets above level 50.\n\"Created by players with the Inscription skill. Can be bought and sold on the auction house.\"\nSell Price:\nRequires Light Parchment (50), Sallow Pigment (5), Roseate Pigment (25)" }
entries[137730] = { ["name"] = "Technique: Glyph of Ghostly Fade", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Ghostly Fade.\nCraft a Glyph of Ghostly Fade.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Ghostly Fade\nClasses: Priest\nUse: Permanently teaches you this glyph.\n\nYou now fade into a more ghostly state.\nSell Price:\nRequires Light Parchment , Sallow Pigment (2), Roseate Pigment (70)" }
entries[137731] = { ["name"] = "Technique: Grimoire of the Fel Imp", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Grimoire of the Fel Imp.\nCraft a Grimoire of the Fel Imp.\nRequires Legion Inscription (1)\nSell Price:\nGrimoire of the Fel Imp\nClasses: Warlock\nUse: Unlocks the Fel Imp pet customization option in the barbershop.\nSell Price:\nRequires Light Parchment , Sallow Pigment (15), Roseate Pigment (5)" }
entries[137732] = { ["name"] = "Technique: Glyph of Sparkles", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Sparkles.\nCraft a Glyph of Sparkles.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Sparkles\nClasses: Mage\nUse: Permanently teaches you this glyph.\n\nYour Slow Fall now has more Sparkles.\nSell Price:\nRequires Light Parchment , Sallow Pigment (6), Roseate Pigment (50)" }
entries[137733] = { ["name"] = "Technique: Glyph of Blackout", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Blackout.\nCraft a Glyph of Blackout.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Blackout\nClasses: Rogue\nUse: Permanently teaches you this glyph.\n\nA good ol' pint saps targets just as well.\nSell Price:\nRequires Light Parchment , Sallow Pigment (10), Roseate Pigment (30)" }
entries[137734] = { ["name"] = "Technique: Glyph of the Sentinel", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of the Sentinel.\nCraft a Glyph of the Sentinel.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of the Sentinel\nClasses: Druid\nUse: Unlocks the Sentinel Flight Form option in the Barber Shop.\nSell Price:\nRequires Light Parchment , Sallow Pigment (4), Roseate Pigment (60)" }
entries[137735] = { ["name"] = "Technique: Glyph of Crackling Crane Lightning", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Crackling Crane Lightning.\nCraft a Glyph of Crackling Crane Lightning.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Crackling Crane Lightning\nClasses: Monk\nUse: Permanently teaches you this glyph.\n\nYour Crackling Jade Lightning visual is altered to the color of the Red Crane celestial. Exclusive with: Glyph of Crackling Tiger Lightning\nSell Price:\nRequires Light Parchment , Sallow Pigment (4), Roseate Pigment (60)" }
entries[137736] = { ["name"] = "Technique: Glyph of the Spectral Raptor", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of the Spectral Raptor.\nCraft a Glyph of the Spectral Raptor.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of the Spectral Raptor\nClasses: Shaman\nUse: Permanently teaches you this glyph.\n\nAlters the appearance of your Ghost Wolf transformation, causing it to resemble a large, spectral raptor.\nSell Price:\nRequires Light Parchment , Sallow Pigment (6), Roseate Pigment (50)" }
entries[137737] = { ["name"] = "Technique: Glyph of Stellar Flare", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Stellar Flare.\nCraft a Glyph of Stellar Flare.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Stellar Flare\nClasses: Hunter\nUse: Permanently teaches you this glyph.\n\nYou now shoot a stellar flare highlighting the target location. Exclusive with: Glyph of the Goblin Anti-Grav Flare\nSell Price:\nRequires Light Parchment , Sallow Pigment (8), Roseate Pigment (40)" }
entries[137738] = { ["name"] = "Technique: Glyph of the Queen", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of the Queen.\nCraft a Glyph of the Queen.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of the Queen\nClasses: Paladin\nUse: Permanently teaches you this glyph.\n\nYour Guardian of Ancient Kings now summons the wrath of a Queen!\nSell Price:\nRequires Light Parchment , Sallow Pigment (2), Roseate Pigment (70)" }
entries[137740] = { ["name"] = "Charred Recipe", ["text"] = "Binds when picked up\nUnique\nRequires Legion Inscription (1)\nSell Price:" }
entries[137741] = { ["name"] = "Technique: Glyph of Fel Touched Souls", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Fel Touched Souls.\nCraft a Glyph of Fel Touched Souls.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Fel Touched Souls\nClasses: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYour Shattered Souls are tainted with Fel. Exclusive with: Glyph of Mana Touched Souls\nSell Price:\nRequires Light Parchment , Sallow Pigment (12), Roseate Pigment (20)" }
entries[137742] = { ["name"] = "Technique: Glyph of Crackling Flames", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Crackling Flames.\nCraft a Glyph of Crackling Flames.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Crackling Flames\nClasses: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYour Immolate crackles with less fel energy appearing almost like normal fire!\nSell Price:\nRequires Light Parchment , Sallow Pigment (12), Roseate Pigment (20)" }
entries[137743] = { ["name"] = "Technique: Glyph of Fallow Wings", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Fallow Wings.\nCraft a Glyph of Fallow Wings.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Fallow Wings\nClasses: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYou now have yellow wings when Glide is active. Exclusive with: Glyph of Fel Wings Glyph of Tattered Wings\nSell Price:\nRequires Light Parchment , Sallow Pigment (12), Roseate Pigment (20)" }
entries[137744] = { ["name"] = "Technique: Glyph of Tattered Wings", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft a Glyph of Tattered Wings.\nCraft a Glyph of Tattered Wings.\nRequires Legion Inscription (1)\nSell Price:\nGlyph of Tattered Wings\nClasses: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYou now have tattered wings when Glide is active. Exclusive with: Glyph of Fallow Wings Glyph of Fel Wings\nSell Price:\nRequires Light Parchment , Sallow Pigment (12), Roseate Pigment (20)" }
entries[137745] = { ["name"] = "Technique: Prophecy Tarot", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Prophecy Tarot.\nCraft a Prophecy Tarot.\nRequires Legion Inscription (1)\nSell Price:\nProphecy Tarot\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 7 Critical Strike\n+ 7 Versatility\n+ 7 Mastery\nSell Price:\nRequires Light Parchment , Sallow Pigment (5), Roseate Pigment (45)\nOptional Reagents: Optional Reagent Slot (#47)" }
