entries[138019] = { ["name"] = "Mythic Keystone", ["text"] = "Binds when picked up\n\"Place within the Font of Power inside the dungeon on Mythic difficulty.\"" }
entries[138020] = { ["name"] = "Meaty Rack of Musken Ribs", ["text"] = "Quest Item\n\"The best in vrykul barbeque.\"" }
entries[138021] = { ["name"] = "Patch of Fine Goat Hair", ["text"] = "Quest Item\n\"This would make a fine sweater.\"" }
entries[138022] = { ["name"] = "Spitefeather's Beak", ["text"] = "Quest Item\n\"This thing nearly took a finger off.\"" }
entries[138023] = { ["name"] = "Stonefang's Jaw", ["text"] = "Quest Item\n\"On closer inspection, the fangs are not actually made of stone.\"" }
entries[138024] = { ["name"] = "Steelscale's Fin", ["text"] = "Quest Item\n\"A fin this size could make quite a bit of soup.\"" }
entries[138026] = { ["name"] = "Empowered Charging Device", ["text"] = "Unique\nUse: Fires an explosive charge of energy at an inactive vehicle within 30 yards.\n\"Curiously emitting a constant, light buzzing sound.\"" }
entries[138027] = { ["name"] = "Portal Key: Sewer Guard Station", ["text"] = "Binds when picked up\nUnique\nUse: Reveal the Underbelly Portal near the guard station." }
entries[138028] = { ["name"] = "Portal Key: Black Market", ["text"] = "Binds when picked up\nUnique\nUse: Reveal the Underbelly Portal near the Black Market." }
entries[138029] = { ["name"] = "Portal Key: Inn Entrance", ["text"] = "Binds when picked up\nUnique\nUse: Reveal the Underbelly Portal near the inn entrance." }
entries[138030] = { ["name"] = "Portal Key: Alchemists' Lair", ["text"] = "Binds when picked up\nUnique\nUse: Reveal the Underbelly Portal within the Alchemists' Lair." }
entries[138031] = { ["name"] = "Portal Key: Abandoned Shack", ["text"] = "Binds when picked up\nUnique\nUse: Reveal the Underbelly Portal near the abandoned shack." }
entries[138032] = { ["name"] = "Portal Key: Rear Entrance", ["text"] = "Binds when picked up\nUnique\nUse: Reveal the Underbelly Portal near the rear entrance." }
entries[138033] = { ["name"] = "Scroll of Command", ["text"] = "Binds when picked up\nUnique\nDuration: 1 hour (real time)\nUse: Read an edict from the Scroll of Command, binding a demon to your will for 2 min. (1 Min Cooldown)" }
entries[138084] = { ["name"] = "Iron Wrought Insignia of Conquest", ["text"] = "Binds when picked up\nTrinket\n+ 6 Versatility\nEquip: When you deal damage you have a chance to gain 12 Agility for 20 sec.\nSell Price:" }
entries[138090] = { ["name"] = "Iron Wrought Insignia of Dominance", ["text"] = "Binds when picked up\nTrinket\n+ 6 Versatility\nEquip: When you deal damage or heal a target you have a chance to gain 12 Intellect for 20 sec.\nSell Price:" }
entries[138093] = { ["name"] = "Iron Wrought Insignia of Victory", ["text"] = "Binds when picked up\nTrinket\nEquip: When you deal damage you have a chance to gain 12 Strength for 20 sec.\nSell Price:" }
entries[138097] = { ["name"] = "Blackfuse's Power Core", ["text"] = "Binds when picked up\n\"He won't be needing it anymore.\"\nSell Price:" }
entries[138098] = { ["name"] = "Iron-Bound Crate of Battlefield Goods", ["text"] = "Binds when picked up\nDuration: 3 days\n\"May contain a piece of equipment.\"\n<Right Click to Open>" }
entries[138099] = { ["name"] = "Skyfire Stone", ["text"] = "Binds when picked up\nUnique (5)\nDuration: 1 hour (real time)\nUse: Summon a Fel Meteor to a target location, inflicting Fire damage and stunning enemies within 10. (1 Min Cooldown)" }
entries[138100] = { ["name"] = "Pest-Be-Gone Bomb", ["text"] = "Binds when picked up\nUnique (5)\nDuration: 1 hour (real time)\nUse: Throw a pest bomb, creating a gas cloud that inflcits 2 Nature damage per sec. and reduces movement speed by 50% for enemies caught inside it. (1 Min Cooldown)" }
entries[138102] = { ["name"] = "Coded Message", ["text"] = "Quest Item\nUse: Use the Fel Cipher to decrypt the contents of the message. (30 Sec Cooldown)" }
entries[138111] = { ["name"] = "Stormforged Grapple Launcher", ["text"] = "Binds when picked up\nToy\n\"Used to access grapple points throughout Stormheim.\"" }
entries[138112] = { ["name"] = "Skull of the Innocent", ["text"] = "Quest Item\n\"Powerful demonic rituals often call for the intact skull of a pure soul.\"" }
entries[138113] = { ["name"] = "Blood of the Innocent", ["text"] = "Quest Item\n\"Only the darkest magic requires the blood of the truly innocent.\"" }
entries[138114] = { ["name"] = "Gloaming Frenzy", ["text"] = "Gloaming Reef\nBinds when picked up\n\"An albino frenzy with razor sharp teeth. Rarely found around the Gloaming Reef.\"" }
entries[138115] = { ["name"] = "Kalec's Image Crystal", ["text"] = "Binds when picked up\nUnique\nUse: Summons an image of Kalec for 30 sec. (30 Sec Cooldown)" }
entries[138116] = { ["name"] = "Throwing Torch", ["text"] = "Binds when picked up\nUnique (5)\nDuration: 10 min (real time)\nUse: Throw the torch at an enemy, inflicting Fire damage. Any enemies nearby that are Soaked in Grog are set ablaze. (1 Min Cooldown)" }
entries[138117] = { ["name"] = "Spiritual Journey", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Haste\n+ 3 Mastery\nDurability 95 / 95\nClasses: Shaman\nEquip: While Ghost Wolf is active, the remaining cooldown on Feral Spirits recovers 500% faster.\n\"'In order to master the wolf, you must BECOME the wolf!' -Advice of a crazed Vrykul shaman\"\nSell Price:" }
entries[138120] = { ["name"] = "Sister Lilith", ["text"] = "Binds when picked up\n\"Sister Lilith will arrive at the Dreamgrove and you will gain the ability to recruit Dreamgrove Treants who can accompany your Champions on missions.\"" }
entries[138121] = { ["name"] = "Inscribed Leaf of Wisdom", ["text"] = "Binds when picked up\n\"Leafbeard the Storied will grant you the ability to perform research into your Order Advancement Tree.\"" }
entries[138123] = { ["name"] = "Shiny Gold Nugget", ["text"] = "Binds when picked up\n\"It feels a little light.\"" }
entries[138124] = { ["name"] = "Gold-Painted Rock", ["text"] = "Binds when picked up\n\"The paint is so shiny, you'd swear it was real gold!\"\nSell Price:" }
entries[138125] = { ["name"] = "Crystal Clear Gemstone", ["text"] = "Binds when picked up\n\"It's freezing cold to the touch.\"" }
entries[138126] = { ["name"] = "Partially Melted Chunk of Ice", ["text"] = "Binds when picked up\n\"That would explain the temperature.\"\nSell Price:" }
entries[138127] = { ["name"] = "Mysterious Coin", ["text"] = "Binds when picked up\n\"It looks vaguely familiar.\"" }
entries[138128] = { ["name"] = "An Old Venture Coin", ["text"] = "Binds when picked up\n\"These things aren't worth anything anymore!\"\nSell Price:" }
entries[138129] = { ["name"] = "Swatch of Priceless Silk", ["text"] = "Binds when picked up\n\"Soft to the touch, but has a mild odor.\"" }
entries[138130] = { ["name"] = "Piece of an Old Goblin Shirt", ["text"] = "Binds when picked up\n\"The palm tree print should've given it away.\"\nSell Price:" }
entries[138131] = { ["name"] = "Magical Sprouting Beans", ["text"] = "Binds when picked up\n\"Once planted, these should grow a stalk as tall as a mountain!\"" }
entries[138132] = { ["name"] = "Just Normal Beans", ["text"] = "Binds when picked up\n\"What did you expect?\"\nSell Price:" }
entries[138133] = { ["name"] = "Elixir of Endless Wonder", ["text"] = "Binds when picked up\n\"Said to endow its imbiber with wondrous power and wisdom.\"" }
entries[138134] = { ["name"] = "Vial of Questionable Liquid", ["text"] = "Binds when picked up\n\"You're pretty sure it's goblin urine.\"\nSell Price:" }
entries[138135] = { ["name"] = "Rax's Magnifying Glass", ["text"] = "Binds when picked up\nUse: Closely examine the quality of Rax's \"trade goods.\"" }
entries[138136] = { ["name"] = "Shell of Clear Speech", ["text"] = "Quest Item\nUnique\n\"Part of a pair, the shells will allow any sound to pass between them.\"" }
entries[138137] = { ["name"] = "Captain Hjalmar Stahlstrom", ["text"] = "Binds when picked up\n\"Captain Hjalmar Stahlstrom will arrive in the Halls of Valor and you will gain the ability to recruit Valarjar Aspirants who can accompany your Champions on missions.\"" }
entries[138138] = { ["name"] = "Einar the Runecaster", ["text"] = "\"Einar the Runecaster will arrive in your Order Hall and grant you the ability to perform research into your Order Advancement Tree.\"" }
entries[138139] = { ["name"] = "Grimoire of Arcane Ways", ["text"] = "Quest Item\n\"The magic knowledge contained in this book will enable Matron Mother Malevolence to pierce the holy barrier preventing teleportation into the Black Temple.\"" }
