entries[138324] = { ["name"] = "Robe of the Astral Warden", ["text"] = "Binds when picked up\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 3 Versatility\n+ 7 Mastery\nDurability 165 / 165\nClasses: Druid\nGarb of the Astral Warden (0/6)\nRobe of the Astral Warden\nGloves of the Astral Warden\nHood of the Astral Warden\nLeggings of the Astral Warden\nMantle of the Astral Warden\nCloak of the Astral Warden\nLegacy Set: Bonus is inactive\n(2) Set Balance: Lunar and Solar Empowerments also increase the critical strike chance of their corresponding spells by 15%.\n(2) Set Feral: Thrash deals 15% increased damage.\n(2) Set Guardian: Your abilities have an additional 10% chance to trigger Gore.\n(2) Set Restoration: Wild Growth grants you 141 Mastery for 7 sec.\n(4) Set Balance: Starsurge deals 15% increased damage to targets affected by both your Sunfire and Moonfire.\n(4) Set Feral: Shred and Swipe deal 8% increased damage for each Bleed effect you have on the target.\n(4) Set Guardian: Mangle reduces the cost of your next Ironfur or Frenzied Regeneration by 5 Rage, stacking up to 2 times.\n(4) Set Restoration: Each time your Rejuvenation heals a target, it has a 1% chance to jump to a new target at full duration.\nSell Price:" }
entries[138325] = { ["name"] = "Tunic of Enveloped Dissonance", ["text"] = "Binds when picked up\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 7 Haste\n+ 3 Mastery\nDurability 165 / 165\nClasses: Monk\nVestments of Enveloped Dissonance (0/6)\nTunic of Enveloped Dissonance\nGloves of Enveloped Dissonance\nHood of Enveloped Dissonance\nLeggings of Enveloped Dissonance\nPauldrons of Enveloped Dissonance\nCloak of Enveloped Dissonance\nLegacy Set: Bonus is inactive\n(2) Set Brewmaster: Ironskin Brew is 10% more effective.\n(2) Set Windwalker: Reduces the cooldown on Rising Sun Kick by 1 sec.\n(2) Set Mistweaver: Renewing Mist has a 1% increased chance to increase the healing of your next Vivify.\n(4) Set Brewmaster: Tiger Palm reduces the remaining cooldown on your brews by an additional 1 sec.\n(4) Set Windwalker: Using 3 sequentially different abilities grants 71 Mastery for 10 sec.\n(4) Set Mistweaver: Vivify heals your primary target for 25% more, and Essence Font's heal over time duration is increased by 2 sec.\nSell Price:" }
entries[138326] = { ["name"] = "Doomblade Tunic", ["text"] = "Binds when picked up\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 4 Haste\n+ 6 Mastery\nDurability 165 / 165\nClasses: Rogue\nDoomblade Battlegear (0/6)\nDoomblade Tunic\nDoomblade Gauntlets\nDoomblade Cowl\nDoomblade Pants\nDoomblade Spaulders\nDoomblade Shadowwrap\nLegacy Set: Bonus is inactive\n(2) Set Assassination: Mutilate also causes the target to Bleed for 20% additional damage over 8 sec.\n(2) Set Outlaw: Saber Slash has an additional 30% chance to trigger Main Gauche.\n(2) Set Subtlety: Nightblade lasts 2 additional sec per combo point spent.\n(4) Set Assassination: Envenom deals 7% additional damage per Bleed you have on the target.\n(4) Set Outlaw: Run Through has a 25% chance to make your next Saber Slash cost no Energy. (Proc chance: 25%)\n(4) Set Subtlety: Shadowstrike has a 30% chance to generate an additional combo point when used on targets affected by your Nightblade. (Proc chance: 30%)\nSell Price:" }
