entries[138478] = { ["name"] = "Feast of Ribs", ["text"] = "Binds when picked up\nUse: Set out a rack of ribs to feed your entire raid or party!\n\nRestores 5% health and 5% mana per second over 20 sec. If you spend at least 10 seconds eating you will become well fed and gain 10% Stamina for 1 hour.\n\nOnly usable in Battlegrounds.\nSell Price:" }
entries[138479] = { ["name"] = "Potato Stew Feast", ["text"] = "Binds when picked up\nUse: Set out a feast of steak and potatoes to feed your entire raid or party!\n\nRestores 5% health and 5% mana per second over 20 sec. If you spend at least 10 seconds eating you will become well fed and gain 10% Stamina for 1 hour.\n\nOnly usable in Battlegrounds.\nSell Price:" }
entries[138480] = { ["name"] = "Black Harvest Tome", ["text"] = "Binds when picked up\n\"A musty tome, its pages are covered with a scribblings in an ancient language.\"\nSell Price:" }
