entries[138484] = { ["name"] = "Soul Configuration Matrix", ["text"] = "Quest Item\nUnique\n\"It's all very technical and magical at the same time. Best to leave it to the professionals. Or, Jace.\"" }
entries[138485] = { ["name"] = "Vile Spirit Converter", ["text"] = "Quest Item\nUnique\n\"Whatever this things does, it's not good. At least it only does it to vile spirits. Or, so the name says.\"" }
entries[138486] = { ["name"] = "\"Third Wind\" Potion", ["text"] = "Use: Restores 50% of health. Only usable in battlegrounds. (5 Min Cooldown)\n\"A gritty, foul-smelling concoction of smelling salts and seven kinds of brew.\"\nSell Price:" }
entries[138487] = { ["name"] = "Shinfel's Staff of Torment", ["text"] = "Binds when picked up\n\"An evil weapon, wielded by an evil being.\"\nSell Price:" }
entries[138488] = { ["name"] = "Saltwater Potion", ["text"] = "Use: Increase all damage done by 30% for 12 sec. Only usable in battlegrounds.\n\"Distilled from the tears of combatants who couldn't measure up.\"\nSell Price:" }
entries[138489] = { ["name"] = "Kargath's Sacrificed Hands", ["text"] = "Binds when picked up\nThis Item Begins a Quest\nHands\n+30,911 Strength\n+81,594 Stamina\n+ 4,728 Critical Strike\n+ 2,626 Mastery\nClasses: Warrior\n\"In a frustrated rage, Kargath cut off his left hand. Everyone thought he was insane then. It appears that at some point in the Outland, perhaps after consuming the blood of a pit lord, he cut off his other hand too.\"\n<Right Click to Read>\nSell Price:" }
entries[138490] = { ["name"] = "Waterspeaker's Totem", ["text"] = "Binds when picked up\nToy\nClasses: Shaman\nUse: Unleash the Waterspeaker's Totem, causing globes of water to encircle you for 1 hour. Restoration Shamans only. (5 Min Cooldown)\n\"The mark of a great Restoration Shaman.\"\nSell Price:" }
