entries[138726] = { ["name"] = "Shard of Potentiation", ["text"] = "Artifact Power\nBinds when picked up\nUse: Discover the hidden power within at the forge in your class hall to empower your artifact.\n\nConsumes all available items of this type." }
entries[138727] = { ["name"] = "Potion of Defiance", ["text"] = "Use: Reduce all damage taken by 20% for 12 sec. Only usable in battlegrounds. (5 Min Cooldown)\nSell Price:" }
entries[138728] = { ["name"] = "Potion of Trivial Invisibility", ["text"] = "Use: Become invisible for 6 sec. Only usable in battlegrounds. (5 Min Cooldown)\nSell Price:" }
entries[138729] = { ["name"] = "Potion of Heightened Senses", ["text"] = "Use: Increase your chance of detecting invisible or stealthed enemies for 30 sec. Only usable in battlegrounds. (5 Min Cooldown)\nSell Price:" }
entries[138730] = { ["name"] = "Synthebrew Goggles XL", ["text"] = "Cosmetic\nBinds to Warband\nUnique\nHead Cosmetic\nEquip: The goggles simulate the effects of alcohol. The effects can easily be dismissed by removing the goggles.\n\"Warning: Do not wear while mounted.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[138731] = { ["name"] = "Bushel of Apples", ["text"] = "Binds when picked up\nUse: Set out a bushel of apples to feed your entire raid or party's mounts!\n\nRestores 5% health and 5% mana per second over 20 sec. If you spend at least 10 seconds eating you will become well fed and the cast time of your mount spells will be reduced by 50% for 1 hour.\n\nOnly usable in Battlegrounds.\nSell Price:" }
entries[138732] = { ["name"] = "History of the Blade", ["text"] = "Binds when picked up\nSell Price:" }
entries[138733] = { ["name"] = "Shadescale Manipulator", ["text"] = "Quest Item\nUse: Envelops a Shadescale Flyeater in a temporal weirding, making them docile and drawing them to the caster for collection. (6 Sec Cooldown)" }
entries[138760] = { ["name"] = "Commander Ansela", ["text"] = "Binds when picked up\n\"Commander Ansela will arrive at Light's Hope Chapel and you will gain the ability to recruit Squads of Squires who can accompany your Champions on missions.\"" }
entries[138761] = { ["name"] = "Sir Alamande Graythorn", ["text"] = "Binds when picked up\n\"Sir Alamande Graythorn will arrive in your Order Hall and grant you the ability to perform research into your Order Advancement Tree.\"" }
entries[138762] = { ["name"] = "Niskaran Morning Star", ["text"] = "Binds when picked up\nOne-Hand Mace\n6 - 8 Damage Speed 2.60\n(2.7 damage per second)\n+2 [Agility or Strength or Intellect]\n+4 Stamina\n+ 2 Haste\n+ 2 Mastery\nDurability 90 / 90\nSell Price:" }
