entries[138899] = { ["name"] = "Daglop's Infernal Copper Coin", ["text"] = "Binds when picked up\n\"I wish I were a little bit taller.\"\nSell Price:" }
entries[138900] = { ["name"] = "Gravil Goldbraid's Famous Sausage Hat", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Wear the hat. (10 Min Cooldown)\n\"You never sausage a hat!\"" }
entries[138901] = { ["name"] = "Tyrande's Coin", ["text"] = "Binds when picked up\n\"That I might protect those I hold dear, and continue to reflect the grace and light of Elune.\"\nSell Price:" }
entries[138902] = { ["name"] = "Malfurion's Coin", ["text"] = "Binds when picked up\n\"Were we too late to stop the Nightmare?\"\nSell Price:" }
entries[138903] = { ["name"] = "Kur'talos Ravencrest's Spectral Coin", ["text"] = "Binds when picked up\n\"Perhaps if we curb these endless tides of demons, then some color may return to the world.\"\nSell Price:" }
entries[138904] = { ["name"] = "Jarod Shadowsong's Coin", ["text"] = "Binds when picked up\n\"Give my troops the strength to overcome the trials of this land.\"\nSell Price:" }
entries[138905] = { ["name"] = "Penelope Heathrow's Allowance", ["text"] = "Binds when picked up\n\"I kinda wish I was a worgen. Wouldn't that be the coolest?\"\nSell Price:" }
entries[138906] = { ["name"] = "Remulos' Sigil", ["text"] = "Binds when picked up\n\"I give my thanks to the Cenarion Circle. May the mortal druids continue to prove themselves worthy of my father's name.\"\nSell Price:" }
entries[138907] = { ["name"] = "Elothir's Golden Leaf", ["text"] = "Binds when picked up\n\"Hmm... no coins. I wonder if this will suffice?\"\nSell Price:" }
entries[138908] = { ["name"] = "Koda's Sigil", ["text"] = "Binds when picked up\n\"I suppose I might fancy a smackerel of honey.\"\nSell Price:" }
entries[138909] = { ["name"] = "King Mrgl-Mrgl's Coin", ["text"] = "Binds when picked up\n\"Some days, I think the murlocs don't appreciate everything I do for them.\"\nSell Price:" }
entries[138910] = { ["name"] = "Hemet Nesingwary's Bullet", ["text"] = "Binds when picked up\n\"I wish my son would hurry up and have kids already! Also, I want to shoot a moose.\"\nSell Price:" }
entries[138911] = { ["name"] = "Murky's Coin", ["text"] = "Binds when picked up\n\"Mrr glrrrgl mrr glrrgl glrr.\"\nSell Price:" }
entries[138912] = { ["name"] = "Spiritwalker Ebonhorn's Coin", ["text"] = "Binds when picked up\n\"For all the brothers and sisters I've lost.\"\nSell Price:" }
entries[138913] = { ["name"] = "Addie Fizzlebog's Coin", ["text"] = "Binds when picked up\n\"Ooh, ooh! I hope I get to shoot a really cool gun! BLAM!\"\nSell Price:" }
entries[138914] = { ["name"] = "Boomboom Brullingsworth's Coin", ["text"] = "Binds when picked up\n\"Come on, move that shell, Zoom! Just like we practiced!\"\nSell Price:" }
entries[138915] = { ["name"] = "The Candleking's Candlecoin", ["text"] = "Binds when picked up\n\"Me want find candlequeen! Hmm... maybe Jackie interested? Me give her candle, see what happens from there.\"\nSell Price:" }
entries[138916] = { ["name"] = "Torok Bloodtotem's Coin", ["text"] = "Binds when picked up\n\"I hate everything. Everything is horrible.\"\nSell Price:" }
